// ---------------------------------------------------------------- PNG out
function crc32(buf: Buffer): number {
  let table = (crc32 as unknown as { t?: Int32Array }).t;
  if (!table) {
    table = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c;
    }
    (crc32 as unknown as { t?: Int32Array }).t = table;
  }
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type: string, data: Buffer): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, "ascii");
  data.copy(out, 8);
  out.writeUInt32BE(crc32(Buffer.concat([Buffer.from(type, "ascii"), data])), 8 + data.length);
  return out;
}
function encodePNG(): Buffer {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: RGB
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;
  // Two filter strategies; keep the smaller IDAT.
  const rawNone = Buffer.alloc(H * (1 + W * 3));
  const rawUp = Buffer.alloc(H * (1 + W * 3));
  for (let y = 0; y < H; y++) {
    rawNone[y * (1 + W * 3)] = 0;
    rawNone.set(px.subarray(y * W * 3, (y + 1) * W * 3), y * (1 + W * 3) + 1);
    rawUp[y * (1 + W * 3)] = 2;
    for (let i = 0; i < W * 3; i++) {
      const cur = px[y * W * 3 + i];
      const up = y === 0 ? 0 : px[(y - 1) * W * 3 + i];
      rawUp[y * (1 + W * 3) + 1 + i] = (cur - up) & 0xff;
    }
  }
  const idatNone = deflateSync(rawNone, { level: 9 });
  const idatUp = deflateSync(rawUp, { level: 9 });
  const idat = idatUp.length < idatNone.length ? idatUp : idatNone;
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  return Buffer.concat([sig, chunk("IHDR", ihdr), chunk("IDAT", idat), chunk("IEND", Buffer.alloc(0))]);
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output/entry.png";
const outPath = outDir.endsWith(".png") ? outDir : join(outDir, "entry.png");
mkdirSync(dirname(outPath), { recursive: true });
const png = encodePNG();
writeFileSync(outPath, png);
console.log(`wrote ${outPath} (${png.length} bytes, ${W}x${H})`);
